INSERT INTO PLAN_MEMBER (
	PLAN_ID,
	MEMBER_ID,
	PARTICIPANT_TYPE
)
SELECT #{planId},
       #{memberId},
       #{participantType}
  FROM DUAL
 WHERE NOT EXISTS (
       SELECT 1
         FROM PLAN_MEMBER
        WHERE PLAN_ID = #{planId}
          AND MEMBER_ID = #{memberId}
 )
